const fn relation_use(
    name: &'static str,
    id: u32,
    source: TupleSource,
    words: u32,
    multiplicity: MultiplicitySource,
    negative: bool,
) -> RelationUse {
    RelationUse {
        relation: RelationIdentity { name, id },
        challenge_epoch: COMMON_LOOKUP_CHALLENGE_EPOCH,
        denominator: DenominatorLayout {
            tuple: TupleLayout {
                source,
                words,
                relation_id_word: 0,
            },
            alpha_power_start: 0,
            subtract_z: true,
        },
        multiplicity: SignedMultiplicity {
            source: multiplicity,
            sign: if negative {
                MultiplicitySign::Negative
            } else {
                MultiplicitySign::Positive
            },
        },
    }
}

